def fix_spaces(text):
    import re
    return re.sub(r' {3,}', '-', text.replace(' ', '_')).replace('___', '-')

def list_to_float(test_list):
    return [tuple(_to_float(x) for x in row) for row in test_list]

def _to_float(x):
    try:
        return float(x)
    except (TypeError, ValueError):
        return x

def max_length(list1):
    longest = max(list1, key=len)
    return (len(longest), longest)

import re
def text_match_wordz(text):
    return re.search(r'\b\w*z\w*\b', text) is not None
